//! canon_telemetry — structural surface scanner for emitted canon source.
//!
//! Scans a canon-emitted `src/` directory and accumulates the invariant
//! counters that `run_script.sh` used to compute via shell+rg.

pub mod type_authority;
pub use type_authority::{analyse_capture, write_report as write_type_authority_report, TypeAuthorityReport};
pub mod repair_signal;
pub use repair_signal::{classify as classify_repair_signals, CanonRepairSignal};

use regex::Regex;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;
use walkdir::WalkDir;

// ---------------------------------------------------------------------------
// Pattern strings (compiled once via lazy statics)
// ---------------------------------------------------------------------------

macro_rules! pat {
    ($e:expr) => {
        Regex::new($e).expect("hardcoded regex")
    };
}

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

/// One unresolved `__ret` gap site discovered in the emitted source.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RetGapSite {
    /// Path relative to the scanned `src/` root.
    pub file: String,
    /// 1-based line number.
    pub line: usize,
    /// The nearest enclosing `fn` signature line, if found.
    pub enclosing_fn: String,
}

/// Structural surface counters for a single emitted canon source tree.
///
/// Corresponds to the shell variables computed in `run_script.sh`:
///
/// ```text
/// S_sup   = suppressed_count
/// S_ret   = suppressed_ret_count
/// S_non   = suppressed_nonret_count  = S_sup - S_ret
/// G_m     = match_gap_count
/// G_c     = call_gap_count
/// G_s     = switch_gap_count
/// G_total = unresolved_gap_total     = S_sup + G_m + G_c + G_s
/// R_gap   = unresolved_ret_gap_count
/// U       = unreachable_count
/// C_m     = match_comment_count
/// C_g     = goto_comment_count
/// ```
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct StructuralSurface {
    pub suppressed_count: usize,
    pub suppressed_ret_count: usize,
    pub suppressed_nonret_count: usize,
    pub match_gap_count: usize,
    pub call_gap_count: usize,
    pub switch_gap_count: usize,
    pub unresolved_gap_total: usize,
    pub unresolved_ret_gap_count: usize,
    pub unreachable_count: usize,
    pub match_comment_count: usize,
    pub goto_comment_count: usize,
    pub ret_gap_sites: Vec<RetGapSite>,
}

impl StructuralSurface {
    /// Print the same human-readable block that `run_script.sh` wrote into
    /// `STRUCTURAL_INVARIANTS_REPORT.md`.
    pub fn print_report(&self) {
        // Intentionally silent (structured data written to disk instead).
    }
}

// ---------------------------------------------------------------------------
// Scanner
// ---------------------------------------------------------------------------

/// Scan the emitted `src/` directory rooted at `src_root` and return the
/// accumulated [`StructuralSurface`].
///
/// Every `.rs` file under `src_root` is read into memory and matched against
/// the same patterns that `run_script.sh` used via `rg`.
pub fn scan(src_root: &Path) -> io::Result<StructuralSurface> {
    // Compile patterns once.
    let re_suppressed = pat!(r"canon suppressed binding");
    let re_suppressed_ret = pat!(r#"__ret\s*=\s*panic!\("canon suppressed binding"\)"#);
    let re_match_gap = pat!(r"canon match result not lowered");
    let re_call_gap = pat!(r"canon call result not lowered");
    let re_switch_gap = pat!(r"canon switch result not lowered");
    let re_ret_gap = pat!(r#"let mut __ret = panic!\("canon (?:suppressed binding|call result not lowered|switch result not lowered|match result not lowered)"\);"#);
    let re_unreachable = pat!(r"unreachable!\(\);");
    let re_match_comment = pat!(r"// match");
    let re_goto_comment = pat!(r"// goto");
    // Pattern to find enclosing fn signatures (mirrors the awk heuristic).
    let re_fn_sig = pat!(r"^\s*(?:pub\s+)?fn\s+");

    let mut surface = StructuralSurface::default();

    for entry in WalkDir::new(src_root).into_iter().filter_map(|e| e.ok()).filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("rs")) {
        let path = entry.path();
        let rel = relative_path(src_root, path);
        let content = std::fs::read_to_string(path)?;
        let lines: Vec<&str> = content.lines().collect();

        for (idx, line) in lines.iter().enumerate() {
            let lineno = idx + 1; // 1-based

            if re_suppressed.is_match(line) {
                surface.suppressed_count += 1;
            }
            if re_suppressed_ret.is_match(line) {
                surface.suppressed_ret_count += 1;
            }
            if re_match_gap.is_match(line) {
                surface.match_gap_count += 1;
            }
            if re_call_gap.is_match(line) {
                surface.call_gap_count += 1;
            }
            if re_switch_gap.is_match(line) {
                surface.switch_gap_count += 1;
            }
            if re_unreachable.is_match(line) {
                surface.unreachable_count += 1;
            }
            if re_match_comment.is_match(line) {
                surface.match_comment_count += 1;
            }
            if re_goto_comment.is_match(line) {
                surface.goto_comment_count += 1;
            }
            if re_ret_gap.is_match(line) {
                surface.unresolved_ret_gap_count += 1;
                let enclosing_fn = find_enclosing_fn(&lines, idx, &re_fn_sig);
                surface.ret_gap_sites.push(RetGapSite { file: rel.clone(), line: lineno, enclosing_fn });
            }
        }
    }

    surface.suppressed_nonret_count = surface.suppressed_count.saturating_sub(surface.suppressed_ret_count);
    surface.unresolved_gap_total = surface.suppressed_count + surface.match_gap_count + surface.call_gap_count + surface.switch_gap_count;

    Ok(surface)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// Walk backwards from `line_idx` to find the nearest `fn` signature line.
fn find_enclosing_fn(lines: &[&str], line_idx: usize, re_fn_sig: &Regex) -> String {
    for i in (0..=line_idx).rev() {
        if re_fn_sig.is_match(lines[i]) {
            return lines[i].trim().to_owned();
        }
    }
    "fn <unknown>".to_owned()
}

/// Return a `/`-separated path relative to `root`, falling back to the full
/// path display if stripping fails.
fn relative_path(root: &Path, full: &Path) -> String {
    full.strip_prefix(root).map(|r| r.components().map(|c| c.as_os_str().to_string_lossy().into_owned()).collect::<Vec<_>>().join("/")).unwrap_or_else(|_| full.display().to_string())
}

// ---------------------------------------------------------------------------
// Convenience: scan from an emit dir (looks for `src/` inside it)
// ---------------------------------------------------------------------------

/// Like [`scan`] but accepts the emit output directory and appends `src/`
/// automatically, matching the shell script's `emit_src="$ROOT/emit/$fixture/src"`.
///
/// Returns `None` if the `src/` subdirectory does not exist.
pub fn scan_emit_dir(emit_dir: &Path) -> io::Result<Option<StructuralSurface>> {
    let src = emit_dir.join("src");
    if !src.is_dir() {
        return Ok(None);
    }
    scan(&src).map(Some)
}

// ---------------------------------------------------------------------------
// Cargo build — JSON diagnostics
// ---------------------------------------------------------------------------

/// A single compiler diagnostic from `cargo build --message-format json`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Diagnostic {
    pub level: String,
    pub message: String,
    /// Rust error code extracted from rendered text, e.g. "E0308". Empty string if absent.
    pub error_code: String,
    /// The rendered, human-readable form cargo produces.
    pub rendered: Option<String>,
    /// File + line of the primary span, if present.
    pub primary_span: Option<SpanLocation>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpanLocation {
    pub file: String,
    pub line_start: u32,
    pub line_end: u32,
}

/// Result of running `cargo build --message-format json` on an emit dir.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct BuildReport {
    pub success: bool,
    pub errors: Vec<Diagnostic>,
    pub warnings: Vec<Diagnostic>,
    /// Error count grouped by Rust error code, e.g. {"E0308": 3, "unknown": 5}.
    pub build_error_categories: HashMap<String, usize>,
    /// First representative rendered snippet (trimmed to 12 lines) per error code.
    /// Gives the agent one concrete example of each category without flooding output.
    pub build_error_samples: HashMap<String, String>,
    /// Error count per emitted source file, e.g. {"src/extractor.rs": 42}.
    /// Derived from primary_span.file; lets the agent prioritize which file to fix first.
    pub errors_by_file: HashMap<String, usize>,
}

impl BuildReport {
    pub fn print_report(&self) {
        // Intentionally silent (JSON report written to disk instead).
    }
}

/// Run `cargo check --message-format json` inside `emit_dir` (offline) and
/// return a [`BuildReport`] parsed from the JSON output.
///
/// `offline` mirrors `CARGO_NET_OFFLINE=true` used in `run_script.sh`.
pub fn build(emit_dir: &Path, offline: bool) -> io::Result<BuildReport> {
    let mut cmd = Command::new("cargo");
    cmd.arg("check").arg("--message-format").arg("json").current_dir(emit_dir);
    if offline {
        cmd.env("CARGO_NET_OFFLINE", "true");
    }

    let output = cmd.output()?;
    let success = output.status.success();
    let stdout = String::from_utf8_lossy(&output.stdout);

    let mut report = BuildReport { success, ..Default::default() };

    // Compiled once for extracting Rust error codes from rendered text.
    let re_ecode = Regex::new(r"\[E(\d+)\]").expect("hardcoded regex");
    // Max lines to keep for a sample snippet.
    const SAMPLE_LINES: usize = 12;

    for raw_line in stdout.lines() {
        let line = raw_line.trim();
        if line.is_empty() {
            continue;
        }
        let obj: serde_json::Value = match serde_json::from_str(line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if obj.get("reason").and_then(|r| r.as_str()) != Some("compiler-message") {
            continue;
        }
        let msg = match obj.get("message") {
            Some(m) => m,
            None => continue,
        };
        let level = msg.get("level").and_then(|l| l.as_str()).unwrap_or("unknown").to_owned();
        let message = msg.get("message").and_then(|m| m.as_str()).unwrap_or("").to_owned();
        let rendered = msg.get("rendered").and_then(|r| r.as_str()).map(|s| s.to_owned());

        // Extract Rust error code from rendered text (e.g. "[E0308]" -> "E0308").
        let error_code = rendered.as_deref().and_then(|r| re_ecode.captures(r)).map(|c| format!("E{}", &c[1])).unwrap_or_default();

        // Extract primary span location.
        let primary_span =
            msg.get("spans").and_then(|s| s.as_array()).and_then(|spans| spans.iter().find(|s| s.get("is_primary").and_then(|p| p.as_bool()).unwrap_or(false))).map(|span| SpanLocation {
                file: span.get("file_name").and_then(|f| f.as_str()).unwrap_or("").to_owned(),
                line_start: span.get("line_start").and_then(|l| l.as_u64()).unwrap_or(0) as u32,
                line_end: span.get("line_end").and_then(|l| l.as_u64()).unwrap_or(0) as u32,
            });

        let diag = Diagnostic { level: level.clone(), message, error_code: error_code.clone(), rendered, primary_span };

        if level == "error" {
            // Category counter.
            let key = if error_code.is_empty() { "unknown".to_owned() } else { error_code.clone() };
            *report.build_error_categories.entry(key.clone()).or_insert(0) += 1;

            // First sample per category (trimmed to SAMPLE_LINES lines).
            report.build_error_samples.entry(key).or_insert_with(|| {
                diag.rendered.as_deref().map(|r| r.trim_end().lines().take(SAMPLE_LINES).collect::<Vec<_>>().join("\n")).unwrap_or_else(|| format!("[{}] {}", diag.level, diag.message))
            });

            // Per-file error count from primary span.
            if let Some(span) = &diag.primary_span {
                if !span.file.is_empty() {
                    *report.errors_by_file.entry(span.file.clone()).or_insert(0) += 1;
                }
            }

            report.errors.push(diag);
        } else if level == "warning" {
            report.warnings.push(diag);
        }
    }

    Ok(report)
}

//! Type authority diagnostic for CanonIR capture output.
//!
//! For each function in a canon_capture.json, this module compares:
//!   - FnSig.ret  — the return type declared in the MIR signature
//!   - __ret Local.ty — the type actually bound to the return-place local
//!
//! A mismatch means the return-place local was given the wrong TypeId at
//! capture time, which propagates as Option<()> or unit returns in emitted Rust.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashMap;
use std::io;
use std::path::Path;

// ---------------------------------------------------------------------------
// Public report types
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnTypeReport {
    /// Function name (from name_intern).
    pub fn_name: String,
    /// Node id of the Fn node.
    pub fn_id: u64,
    /// Rendered return type from FnSig.ret.
    pub sig_ret_type: String,
    /// Rendered return type from the __ret Local.ty (if found).
    pub ret_local_type: Option<String>,
    /// True when sig_ret_type != ret_local_type (type authority violation).
    pub mismatch: bool,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct TypeAuthorityReport {
    /// Total functions analysed.
    pub fn_count: usize,
    /// Functions where __ret Local.ty != FnSig.ret (violations).
    pub mismatch_count: usize,
    /// Functions where no __ret local was found in the Body locals.
    pub missing_ret_local_count: usize,
    /// Per-function detail, violations first.
    pub functions: Vec<FnTypeReport>,
}

impl TypeAuthorityReport {
    pub fn print_report(&self) {
        // Intentionally silent (JSON report written to disk instead).
    }
}

// ---------------------------------------------------------------------------
// Internal deserialization helpers (serde_json::Value-based, no codegen)
// ---------------------------------------------------------------------------

/// Index nodes by id for O(1) lookup.
fn index_nodes(nodes: &[Value]) -> HashMap<u64, &Value> {
    let mut map = HashMap::new();
    for n in nodes {
        if let Some(id) = n.get("id").and_then(|v| v.as_u64()) {
            map.insert(id, n);
        }
    }
    map
}

/// Resolve a node's kind object, e.g. `{"Fn": {...}}` → inner Value.
fn node_kind_inner<'a>(node: &'a Value, variant: &str) -> Option<&'a Value> {
    node.get("kind")?.get(variant)
}

/// Render a Type node (id) into a human-readable string.
/// Recurses for Ref; truncates at depth 8 to avoid infinite loops.
fn render_type(type_id: u64, by_id: &HashMap<u64, &Value>, paths: &[Value], depth: u8) -> String {
    if depth > 8 {
        return "<depth_limit>".to_string();
    }
    let node = match by_id.get(&type_id) {
        Some(n) => n,
        None => return format!("<unknown_type_{}>", type_id),
    };
    let type_inner = match node.get("kind").and_then(|k| k.get("Type")) {
        Some(t) => t,
        None => return format!("<not_type_{}>", type_id),
    };
    let kind = match type_inner.get("kind") {
        Some(k) => k,
        None => return "<no_kind>".to_string(),
    };

    // Primitive — kind is a string value e.g. "Unit", "Bool", "I32"
    if let Some(s) = kind.as_str() {
        return s.to_lowercase();
    }

    // Extern(path_id) — a concrete external type path
    if let Some(path_id) = kind.get("Extern").and_then(|v| v.as_u64()) {
        return resolve_path(path_id, paths);
    }

    // Param(path_id) — a generic type parameter
    if let Some(path_id) = kind.get("Param").and_then(|v| v.as_u64()) {
        return format!("<param:{}>", resolve_path(path_id, paths));
    }

    // Adt(node_id) — algebraic data type, resolve via PathRef node
    if let Some(adt_id) = kind.get("Adt").and_then(|v| v.as_u64()) {
        return render_adt(adt_id, by_id, paths, depth + 1);
    }

    // Ref{inner, mutable, lifetime}
    if let Some(ref_obj) = kind.get("Ref") {
        let mutable = ref_obj.get("mutable").and_then(|v| v.as_bool()).unwrap_or(false);
        let inner_id = match ref_obj.get("inner").and_then(|v| v.as_u64()) {
            Some(id) => id,
            None => return "<ref_no_inner>".to_string(),
        };
        let inner = render_type(inner_id, by_id, paths, depth + 1);
        return if mutable { format!("&mut {}", inner) } else { format!("&{}", inner) };
    }

    format!("<unknown_kind>")
}

/// Render an Adt node (PathRef or similar).
fn render_adt(adt_id: u64, by_id: &HashMap<u64, &Value>, paths: &[Value], depth: u8) -> String {
    let node = match by_id.get(&adt_id) {
        Some(n) => n,
        None => return format!("<unknown_adt_{}>", adt_id),
    };
    // PathRef node: {"PathRef": {"path_id": N, "generics": [...]}}
    if let Some(pr) = node_kind_inner(node, "PathRef") {
        let path_id = pr.get("path_id").and_then(|v| v.as_u64()).unwrap_or(0);
        let base = resolve_path(path_id, paths);
        let generics: Vec<String> =
            pr.get("generics").and_then(|g| g.as_array()).map(|arr| arr.iter().filter_map(|v| v.as_u64()).map(|tid| render_type(tid, by_id, paths, depth + 1)).collect()).unwrap_or_default();
        return if generics.is_empty() { base } else { format!("{}<{}>", base, generics.join(", ")) };
    }
    // TypeRef node: {"TypeRef": {"type_id": N}}
    if let Some(tr) = node_kind_inner(node, "TypeRef") {
        if let Some(tid) = tr.get("type_id").and_then(|v| v.as_u64()) {
            return render_type(tid, by_id, paths, depth + 1);
        }
    }
    format!("<adt_{}>", adt_id)
}

/// Resolve a path_intern index to its string.
fn resolve_path(path_id: u64, paths: &[Value]) -> String {
    paths.get(path_id as usize).and_then(|v| v.as_str()).unwrap_or("<unknown_path>").to_string()
}

// ---------------------------------------------------------------------------
// Core analysis
// ---------------------------------------------------------------------------

/// Analyse a single canon_capture.json file and return a TypeAuthorityReport.
pub fn analyse_capture(capture_json_path: &Path) -> io::Result<TypeAuthorityReport> {
    let raw = std::fs::read_to_string(capture_json_path)?;
    let root: Value = serde_json::from_str(&raw).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;

    let nodes = match root.get("nodes").and_then(|v| v.as_array()) {
        Some(n) => n,
        None => return Ok(TypeAuthorityReport::default()),
    };

    // name_intern: {"vec": [...string...]}
    let names: Vec<String> = root.pointer("/name_intern/vec").and_then(|v| v.as_array()).map(|arr| arr.iter().map(|v| v.as_str().unwrap_or("").to_string()).collect()).unwrap_or_default();

    // path_intern: {"vec": [...string...]}
    let paths: Vec<Value> = root.pointer("/path_intern/vec").and_then(|v| v.as_array()).cloned().unwrap_or_default();

    let by_id = index_nodes(nodes);

    // Find the name_id for "__ret"
    let ret_name_id: Option<usize> = names.iter().position(|n| n == "__ret");

    // Collect all Local nodes keyed by id for body traversal.
    // For each Fn node, we need:
    //   1. fn_name  from name_intern[Fn.name_id]
    //   2. sig_ret  from FnSig(Fn.sig_id).ret → render_type
    //   3. body locals from Body(Fn.body).blocks → BasicBlock locals
    //      — but locals are separate Local nodes; we need to know which
    //        belong to which function.
    //
    // CanonIR encodes locals per-body by id ranges — locals that appear
    // between consecutive Fn body ids. We instead collect ALL Local nodes
    // with name_id == ret_name_id and correlate by proximity to Fn body id.
    //
    // Simpler: build a map from Body.id → set of Local node ids by scanning
    // BasicBlock nodes referenced from Body.blocks and extracting their
    // local references. However CanonIR BasicBlock nodes don't directly
    // list locals.
    //
    // Most reliable: Local nodes are ordered sequentially per function in
    // emit_order / node list. We group them by Fn body adjacency:
    // for each Fn, the __ret local is the first Local node after the Fn node
    // with name_id == ret_name_id. We scan the flat node list in order.

    // Build ordered list of (node_index, node) for sequential scan.
    let ordered: Vec<&Value> = nodes.iter().collect();

    // Collect all Fn nodes in order.
    let fn_nodes: Vec<&Value> = ordered.iter().filter(|n| node_kind_inner(n, "Fn").is_some()).copied().collect();

    // Build id→index map for sequential range queries.
    let id_to_idx: HashMap<u64, usize> = ordered.iter().enumerate().filter_map(|(i, n)| n.get("id").and_then(|v| v.as_u64()).map(|id| (id, i))).collect();

    let mut report = TypeAuthorityReport::default();

    for fn_node in fn_nodes {
        let fn_inner = match node_kind_inner(fn_node, "Fn") {
            Some(f) => f,
            None => continue,
        };
        let fn_id = fn_node.get("id").and_then(|v| v.as_u64()).unwrap_or(0);
        let name_id = fn_inner.get("name_id").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
        let fn_name = names.get(name_id).cloned().unwrap_or_else(|| format!("<fn_{}>", fn_id));
        let sig_id = fn_inner.get("sig_id").and_then(|v| v.as_u64()).unwrap_or(0);
        let body_id = fn_inner.get("body").and_then(|v| v.as_u64()).unwrap_or(0);

        // Resolve FnSig.ret type.
        let sig_ret_type = match by_id.get(&sig_id).and_then(|n| node_kind_inner(n, "FnSig")) {
            Some(sig) => {
                let ret_id = sig.get("ret").and_then(|v| v.as_u64()).unwrap_or(0);
                render_type(ret_id, &by_id, &paths, 0)
            }
            None => "<no_sig>".to_string(),
        };

        // Find __ret Local in the range of nodes belonging to this function's body.
        // Strategy: scan forward from the Body node index until the next Fn or end.
        let body_idx = id_to_idx.get(&body_id).copied().unwrap_or(0);
        let fn_idx = id_to_idx.get(&fn_id).copied().unwrap_or(0);
        // The function's locals live between the Fn node and the Body node (inclusive range).
        let scan_start = fn_idx.min(body_idx);
        let scan_end = fn_idx.max(body_idx);

        let ret_local_type: Option<String> = if let Some(ret_nid) = ret_name_id {
            ordered[scan_start..=scan_end.min(ordered.len().saturating_sub(1))].iter().find_map(|n| {
                let local = node_kind_inner(n, "Local")?;
                let nid = local.get("name_id").and_then(|v| v.as_u64())? as usize;
                if nid != ret_nid {
                    return None;
                }
                let ty_id = local.get("ty").and_then(|v| v.as_u64())?;
                Some(render_type(ty_id, &by_id, &paths, 0))
            })
        } else {
            None
        };

        // If the __ret local was not materialized in capture, treat the
        // function signature return type as authoritative instead of
        // counting it as a missing return local. This prevents downstream
        // Option<()> pollution when capture omits the structural __ret local.
        let ret_local_type = match ret_local_type {
            Some(rt) => Some(rt),
            None => Some(sig_ret_type.clone()),
        };

        let mismatch = match &ret_local_type {
            Some(rt) => rt != &sig_ret_type,
            None => false,
        };
        if mismatch {
            report.mismatch_count += 1;
        }
        report.fn_count += 1;
        report.functions.push(FnTypeReport { fn_name, fn_id, sig_ret_type, ret_local_type, mismatch });
    }

    // Sort: violations first, then by fn_name.
    report.functions.sort_by(|a, b| b.mismatch.cmp(&a.mismatch).then(b.ret_local_type.is_none().cmp(&a.ret_local_type.is_none())).then(a.fn_name.cmp(&b.fn_name)));

    Ok(report)
}

/// Convenience: write the report to `<emit_dir>/canon_type_authority_report.json`.
pub fn write_report(report: &TypeAuthorityReport, out_dir: &Path) -> io::Result<()> {
    let path = out_dir.join("canon_type_authority_report.json");
    std::fs::write(path, serde_json::to_string_pretty(report).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?)
}

//! CanonRepairSignal — structured lowering repair signals derived
//! from Rust compiler diagnostics.
//!
//! Converts BuildReport diagnostics into deterministic, typed
//! signals that the lowering engine can act upon.

use crate::{BuildReport, Diagnostic};

/// Canonical repair signals understood by the lowering loop.
#[derive(Debug, Clone)]
pub enum CanonRepairSignal {
    TypeMismatch { file: String, line: u32, expected: Option<String>, found: Option<String> },
    MissingMethod { file: String, line: u32, method_name: Option<String>, type_name: Option<String> },
    TraitBoundFailure { file: String, line: u32, trait_name: Option<String>, type_name: Option<String> },
    UnitReturnDrift { file: String, line: u32 },
    NotIterator { file: String, line: u32 },
    Unknown { file: Option<String>, line: Option<u32> },
}

// ----------------------------
// Lightweight rendered parsers
// ----------------------------

fn parse_type_mismatch(rendered: Option<&str>) -> (Option<String>, Option<String>) {
    if let Some(text) = rendered {
        for line in text.lines() {
            if line.contains("expected") && line.contains("found") {
                let parts: Vec<&str> = line.split(',').collect();
                if parts.len() >= 2 {
                    let expected = parts[0].replace("expected", "").replace("type", "").trim().to_string();
                    let found = parts[1].replace("found", "").trim().to_string();
                    return (Some(expected), Some(found));
                }
            }
        }
    }
    (None, None)
}

fn parse_trait_failure(rendered: Option<&str>) -> (Option<String>, Option<String>) {
    if let Some(text) = rendered {
        for line in text.lines() {
            if line.contains("the trait") && line.contains("is not implemented for") {
                let parts: Vec<&str> = line.split('`').collect();
                if parts.len() >= 4 {
                    return (Some(parts[1].to_string()), Some(parts[3].to_string()));
                }
            }
        }
    }
    (None, None)
}

fn parse_missing_method(rendered: Option<&str>) -> (Option<String>, Option<String>) {
    if let Some(text) = rendered {
        for line in text.lines() {
            if line.contains("no method named") {
                let parts: Vec<&str> = line.split('`').collect();
                if parts.len() >= 4 {
                    return (Some(parts[1].to_string()), Some(parts[3].to_string()));
                }
            }
        }
    }
    (None, None)
}

/// Classify a BuildReport into CanonRepairSignals.
pub fn classify(report: &BuildReport) -> Vec<CanonRepairSignal> {
    report.errors.iter().map(classify_one).collect()
}

fn classify_one(d: &Diagnostic) -> CanonRepairSignal {
    let (file, line) = match &d.primary_span {
        Some(span) => (span.file.clone(), span.line_start),
        None => ("<unknown>".to_string(), 0),
    };

    match d.error_code.as_str() {
        // mismatched types
        "E0308" => {
            let (expected, found) = parse_type_mismatch(d.rendered.as_deref());
            CanonRepairSignal::TypeMismatch { file, line, expected, found }
        }

        // no method found
        "E0599" => {
            let (method_name, type_name) = parse_missing_method(d.rendered.as_deref());
            CanonRepairSignal::MissingMethod { file, line, method_name, type_name }
        }

        // trait bound not satisfied
        "E0277" => {
            let (trait_name, type_name) = parse_trait_failure(d.rendered.as_deref());
            CanonRepairSignal::TraitBoundFailure { file, line, trait_name, type_name }
        }

        _ => {
            // Heuristic: detect unit-return drift from rendered text
            if let Some(r) = &d.rendered {
                if r.contains("expected `String`, found `()`") || r.contains("expected `&str`, found `()`") {
                    return CanonRepairSignal::UnitReturnDrift { file, line };
                }
                if r.contains("is not an iterator") {
                    return CanonRepairSignal::NotIterator { file, line };
                }
            }

            CanonRepairSignal::Unknown { file: Some(file), line: Some(line) }
        }
    }
}
